// SoulEngine 构造函数（伪代码）
class SoulEngine:
    def __init__(
        llm,              // LLM 服务
        memory,           // 记忆管理
        // --- 推测兴趣配置 ---
        speculation_interval = 10min,    // 推测生成间隔
        speculation_ttl = 3days,         // 推测有效期
        speculation_cooldown = 7days,    // 拒绝后冷却期
        confirmation_threshold = 3,      // 3次验证 → 提升为正式兴趣
        max_active_speculations = 5,     // 最大活跃推测数
        // --- 画像整合配置 ---
        consolidation_interval = 12h,    // 与认知循环同步
        // --- 反馈与姿态门控 ---
        feedback_batch_threshold = 3,    // 3次反馈触发批量处理
        posture_gate_mode = "shadow",    // shadow=仅记录不过滤
    ):
        self.llm = llm
        self.memory = memory
        // 认知 Prompt 视图：不同层使用不同的压缩策略
        self.preference_view = normalize_view(preference_prompt_view)
        self.awareness_view  = normalize_view(awareness_prompt_view)
        self.insight_view    = normalize_view(insight_prompt_view)

// 画像重建触发机制（伪代码）

// 三种重建触发器，每种对应不同的审计日志写入点
TRIGGERS = {
    "dialogue":             "dialogue_soul_rebuild",      // 对话学习触发
    "feedback_batch":       "feedback_soul_rebuild",      // 反馈批次触发
    "confirmed_hypotheses": "hypotheses_soul_rebuild",    // 假设确认触发
}

// 核心不变量：假设只有被验证 AND 置信度 >= 0.75 时才能触发灵魂重建
MIN_CONFIDENCE = 0.75

// 深层候选类型：只有 goal/value/state 类型的对话学习
// 才通过姿态门控写入深层画像（interest/dislike 走快速通道）
DEEP_CANDIDATE_KINDS = {goal, value, state}

// 设计决策：为什么阈值是 0.75 而不是 0.5？
// 灵魂重建是高成本操作（完整 LLM 调用），且影响所有下游模块。
// 0.75 确保只有「相当确信」的假设才能触发重建，
// 避免低质量信号导致画像频繁抖动。

// analyze_events() 核心流程（伪代码）

async def analyze_events(events, existing_preference):
    events = filter_events(events)  // 过滤满意度事件

    // 关键设计：大批次自动拆分并发，避免单次 LLM 调用超时
    if len(events) >= chunk_size:
        return await analyze_chunked(events)  // 并发调用 LLM，逐层合并

    // 单批次路径：构建 Prompt 并检查是否超出 token 预算
    prompt = build_preference_analysis_prompt(events, existing_preference)

    if prompt_chars > max_prompt_chars:
        // Prompt 太长 → 自动拆分为适配窗口的 chunk
        return await analyze_chunked(plan_fitting_chunks(events))

    // 正常单批次分析
    return await analyze_single(events)

